#!/bin/bash
# =============================================================================
# devhost — run agent dev work on the BUILD HOST (node-2), not on the primary.
#
# Edit files on the primary as usual (your own git worktree — never /opt/nxeon),
# then run every heavy command through this helper. It mirrors your worktree's
# source to node-2 (/tank/nxeon-build/wt/<name>, own node_modules there), runs the
# command inside the capped nxeon-build-agents.slice with a THROWAWAY database
# (Postgres on node-2 127.0.0.1:5433), and streams the output back.
#
#   scripts/devhost run [--lock] [--max SEC] -- CMD...   push + run CMD in the node-2 copy
#   scripts/devhost tsc                                  = run -- npx tsc --noEmit
#   scripts/devhost test [FILES...]                      = run --lock -- npx tsx --test ...
#   scripts/devhost build                                = run --lock -- npx next build
#   scripts/devhost dev [--port P]                       start `next dev` on node-2 (background unit)
#   scripts/devhost bg NAME [--port P] -- CMD...         any background process (worker, preview server)
#   scripts/devhost stop [NAME|all]                      stop this worktree's background units
#   scripts/devhost logs [NAME] [-n N] [-f]              journal of a background unit (default: dev)
#   scripts/devhost tunnel PORT [LOCAL_PORT]             ssh -L so the primary can curl/Playwright it
#   scripts/devhost pull REMOTE_PATH [LOCAL_DEST]        copy results (screenshots, reports) back
#   scripts/devhost push                                 just sync files (run does this itself)
#   scripts/devhost install                              force npm install + prisma generate there
#   scripts/devhost db push|reset|info                   throwaway DB: schema push / recreate / name
#   scripts/devhost env set KEY=VALUE | unset KEY | list extra env for this worktree (never prod secrets)
#   scripts/devhost rm                                   stop units, drop the throwaway DB, delete the node-2 copy
#   scripts/devhost ls | status | sync                   workspaces / node-2 load / push refs to node-2's mirror
#
# Rules: /root/agent-notes/BUILD-HOST.md. The node-2 copy is a build/run sandbox,
# not a place to edit or commit — your primary-side worktree stays the source of truth.
# =============================================================================
set -euo pipefail
HERE="$(dirname "$(readlink -f "$0")")"
# shellcheck source=lib/buildhost-env.sh
source "$HERE/lib/buildhost-env.sh"
REPO="${DEVHOST_REPO:-/opt/nxeon}"

die() { echo "devhost: $*" >&2; exit 1; }
say() { echo "devhost: $*" >&2; }
q() { printf '%q ' "$@"; }

# ---- workspace identity -----------------------------------------------------
worktree_root() {
  local top; top=$(git rev-parse --show-toplevel 2>/dev/null) || die "run this inside your own git worktree of the Nxeon repo"
  top=$(readlink -f "$top")
  case "$top" in
    /opt/nxeon|/opt/nxeon-staging|/tank/nxeon-deploy/*) die "$top is a live/deploy tree. Create your own worktree first:  git -C /opt/nxeon worktree add /tank/dev-worktrees/<name> -b <branch> main" ;;
  esac
  [ -L "$top/.next" ] && die "$top/.next is a symlink (a live tree) — refusing"
  [ -L "$top/node_modules" ] && say "warning: $top/node_modules is a symlink — never 'git add -A' here (see BUILD-HOST.md). devhost does not need local node_modules at all."
  echo "$top"
}
ws_name() {
  local top="$1" n
  n=$(basename "$top" | tr 'A-Z' 'a-z' | tr -c 'a-z0-9-\n' '-' | sed -E 's/-+/-/g; s/^-//; s/-$//' | cut -c1-40)
  [ -n "$n" ] || n=wt
  echo "${DEVHOST_NAME:-$n}"
}
init_ws() {
  TOP=$(worktree_root); NAME=$(ws_name "$TOP")
  case "$NAME" in *[!a-z0-9-]*|"") die "bad workspace name '$NAME' (DEVHOST_NAME=...)";; esac
"use strict";
// Cyrus perf safety (2026-10-11, after the ChunkMirror incident): the WATCHDOG injection and the PERF pre-check.
//
// inject(ws, rec): before every javac of a generated (not imported) plugin, place the audited watchdog sources
//   (perf/src/NxPerf*.java) into <main package>.nxperf, call NxPerf.init(this) first thing in onEnable (added when
//   missing), point any NxPerf import at that package, and append the perf: section to config.yml. The files are
//   overwritten on every round, so the model can never ship a modified watchdog. Pure file edits, deterministic.
// perfcheck(files): source heuristics for unbounded work (world-wide iteration, spawns/explosions in loops, raw
//   repeating tasks, recursion through the plugin's own events, huge radius/per-tick literals) without the NxPerf
//   bounds. Hits go back to the model like pre-check problems (each once); they never block a build on their own.
// MB_PERF_SAFETY=0 turns both off (default on).

const fs = require("fs");
const path = require("path");

const PERF_VERSION = "nxperf-2";
const SRC_DIR = path.join(__dirname, "perf", "src");
const FILES = ["NxPerfCore.java", "NxPerf.java"];
const enabled = (env = process.env) => !/^(0|false|off)$/i.test(String(env.MB_PERF_SAFETY ?? "").trim());

const CONFIG_SECTION = `
# Performance safety (added by Nxeon). If the server stays under tps-floor for window-seconds while this mod
# causes the lag, its heavy features pause (the server keeps running) and the log says which setting triggered it.
# /<command> perf status shows the numbers. Every value below is a DEFAULT you may change: values above the
# recommended maximum are applied and logged once as a warning; auto-disable: false means it never pauses on its own.
perf:
  # Pause heavy features automatically when this mod lags the server (false = never; perf status still reports lag)
  auto-disable: true
  # TPS under which the mod counts as lagging the server, for window-seconds in a row (recommended 5 or more)
  tps-floor: 15.0
  window-seconds: 10
  # Work units per tick for each feature; a bigger job is spread over the next ticks (recommended 256 or less)
  max-work-per-tick: 64
  # Milliseconds of each 50 ms tick this mod may use before it counts as too heavy (recommended 45 or less)
  max-ms-per-tick: 25.0
  # One tick of this mod's code longer than this pauses it at once
  freeze-ms: 2000.0
  # Spawns per second / living mobs per chunk for each feature (recommended 50 / 100 or less)
  max-entities-per-second: 5
  max-entities-per-chunk: 20
  # Queued work items per feature (recommended 20000 or less: memory)
  max-queue: 2000
  # This server's own cap on the radius (blocks) the mod uses; 0 = no cap, the mod's configured radius is used
  max-radius: 0
  # Entities this mod's own code may spawn per second before spawns are cancelled (recommended 500 or less)
  max-spawns-per-second: 50
`;

function readPluginYml(ws) {
  const p = path.join(ws, "src/main/resources/plugin.yml");
  try { return fs.readFileSync(p, "utf8"); } catch { return null; }
}
function mainClassOf(yml) {
  const m = /^main:\s*['"]?([A-Za-z_$][\w$]*(?:\.[A-Za-z_$][\w$]*)+)['"]?\s*$/m.exec(yml || "");
  return m ? m[1] : null;
}
/**
 * The package the watchdog WILL be injected into (<main package>.nxperf), known before PERF.inject runs (it runs inside
 * compile(), after the first autofix/pre-check round). Null when plugin.yml names no main class.
 */
function perfPackageOf(ws) {
  const main = mainClassOf(readPluginYml(ws));
  return main ? `${main.slice(0, main.lastIndexOf("."))}.nxperf` : null;
}
const sourceOf = (ws, fqn) => path.join(ws, "src/main/java", ...fqn.split(".")) + ".java";

/** The watchdog sources for a package (exported for tests and fixtures). */
function watchdogSources(pkg) {
  if (!/^[a-z_][a-z0-9_]*(\.[a-z_][a-z0-9_]*)*$/.test(pkg)) throw new Error(`bad package ${pkg}`);
  return FILES.map((f) => ({ name: f, content: fs.readFileSync(path.join(SRC_DIR, f), "utf8").replace(/@PKG@/g, pkg) }));
}

/** Insert NxPerf.init(this) as the first statement of onEnable (or add an onEnable). Returns the new text or null if unchanged. */
function patchMain(src, perfPkg, className) {
  if (/\bNxPerf\s*\.\s*init\s*\(\s*this\s*\)/.test(src)) return null;
  const call = `${perfPkg}.NxPerf.init(this); // Nxeon performance safety (added by the build service)`;
  const m = /\bvoid\s+onEnable\s*\(\s*\)\s*(?:throws\s+[\w.,\s]+)?\{/.exec(src);
  if (m) return src.slice(0, m.index + m[0].length) + `\n    ${call}` + src.slice(m.index + m[0].length);
  // no onEnable: add one before the class's closing brace
  const cls = new RegExp(`\\bclass\\s+${className}\\b`).exec(src);
  const end = src.lastIndexOf("}");
  if (!cls || end < cls.index) return null;
  return `${src.slice(0, end)}\n  @Override\n  public void onEnable() {\n    ${call}\n  }\n${src.slice(end)}`;
}

/**
 * Place the watchdog into a generated workspace. Returns { injected, reason?, pkg?, mainPatched?, configSection? }.
 * Never throws for a workspace it cannot handle (validate()/javac report those); imported plugins are left alone.
 */
function inject(ws, rec = {}, env = process.env) {
  if (!enabled(env)) return { injected: false, reason: "MB_PERF_SAFETY is off" };
  if (rec.imported) return { injected: false, reason: "imported plugin (the owner's own code is not changed)" };
  const main = mainClassOf(readPluginYml(ws));
  if (!main) return { injected: false, reason: "no main class in plugin.yml" };
  const mainFile = sourceOf(ws, main);
  if (!fs.existsSync(mainFile)) return { injected: false, reason: `main class source ${main} not found` };
  const pkg = main.slice(0, main.lastIndexOf("."));
  const perfPkg = `${pkg}.nxperf`;
  const dir = path.join(ws, "src/main/java", ...perfPkg.split("."));
  fs.mkdirSync(dir, { recursive: true });
  for (const f of watchdogSources(perfPkg)) fs.writeFileSync(path.join(dir, f.name), f.content);
  // any NxPerf import the model wrote points at the injected package
  const javaRoot = path.join(ws, "src/main/java");
  const walk = (d) => fs.readdirSync(d, { withFileTypes: true }).flatMap((e) => (e.isDirectory() ? walk(path.join(d, e.name)) : e.name.endsWith(".java") ? [path.join(d, e.name)] : []));
  for (const f of walk(javaRoot)) {
    if (path.dirname(f) === dir) continue;
    const s = fs.readFileSync(f, "utf8");
    const t = s.replace(/^import\s+(?:static\s+)?[\w.]*\bnxperf\.(NxPerf(?:Core)?)\s*;/gm, (_m, cls) => `import ${perfPkg}.${cls};`)
      .replace(/^import\s+dev\.nxeon\.cyrus\.perf\.(NxPerf(?:Core)?)\s*;/gm, (_m, cls) => `import ${perfPkg}.${cls};`);
    if (t !== s) fs.writeFileSync(f, t);
  }
  const src = fs.readFileSync(mainFile, "utf8");
  const patched = patchMain(src, perfPkg, main.slice(main.lastIndexOf(".") + 1));
  if (patched) fs.writeFileSync(mainFile, patched);
  const cfg = path.join(ws, "src/main/resources/config.yml");
  let configSection = false;
  if (fs.existsSync(cfg)) {
    const y = fs.readFileSync(cfg, "utf8");
    if (!/^perf\s*:/m.test(y)) { fs.writeFileSync(cfg, y.replace(/\s*$/, "\n") + CONFIG_SECTION); configSection = true; }
  }
  const r = { injected: true, version: PERF_VERSION, pkg: perfPkg, mainPatched: !!patched, configSection };
  rec.perf = r;
  return r;
}

// ------------------------------------------------------------------ PERF pre-check ----
const stripComments = (s) => s.replace(/\/\*[\s\S]*?\*\//g, (m) => m.replace(/[^\n]/g, " ")).replace(/\/\/[^\n]*/g, "").replace(/"(?:[^"\\\n]|\\.)*"/g, '""');

/** Line ranges of loop bodies (for/while/do + forEach), by brace matching on comment- and string-free text. */
function loopRanges(src) {
  const out = [];
  const re = /\b(for|while)\s*\(|\bdo\s*\{|\.forEach\s*\(/g;
  let m;
  while ((m = re.exec(src))) {
    let i = src.indexOf("{", m.index);
    if (i < 0) continue;
    // for/while: skip the header parens first
    if (!m[1] && /;/.test(src.slice(m.index, i))) continue; // forEach(this::x); has no body
    if (m[1]) { let d = 0, j = src.indexOf("(", m.index); for (; j < src.length; j++) { if (src[j] === "(") d++; else if (src[j] === ")" && --d === 0) break; } i = src.indexOf("{", j); if (i < 0 || /[;]/.test(src.slice(j + 1, i))) continue; }
    let d = 0, k = i;
    for (; k < src.length; k++) { if (src[k] === "{") d++; else if (src[k] === "}" && --d === 0) break; }
    out.push([lineAt(src, m.index), lineAt(src, k)]);
  }
  return out;
}
const lineAt = (s, i) => s.slice(0, i).split("\n").length;

/** Handler method ranges (@EventHandler ... { ... }). */
function handlerRanges(src) {
  const out = [];
  const re = /@EventHandler\b[^{;]*?\(\s*(?:final\s+)?(\w+)\s+\w+\s*\)\s*(?:throws[^{]*)?\{/g;
  let m;
  while ((m = re.exec(src))) {
    let d = 0, k = m.index + m[0].length - 1;
    for (; k < src.length; k++) { if (src[k] === "{") d++; else if (src[k] === "}" && --d === 0) break; }
    out.push({ event: m[1], from: lineAt(src, m.index), to: lineAt(src, k) });
  }
  return out;
}

const PERF_RULES = [
  { id: "perf-world-iteration", re: /\.(getLoadedChunks|getEntities|getLivingEntities|getEntitiesByClass|getEntitiesByClasses)\s*\(\s*\)/, ctx: "any", bounded: /NxPerf\s*\.\s*(take|queue|remaining)\b/,
    fix: "Iterating every loaded chunk or entity of a world ($1) has no upper bound. Use getNearbyEntities(radius) around a player with NxPerf.radius(...), or put the work into an NxPerf.queue(...) / check NxPerf.take(...) so at most perf.max-work-per-tick items run per tick." },
  { id: "perf-spawn-in-loop", re: /\.(spawnEntity|spawn|spawnFallingBlock|dropItem|dropItemNaturally)\s*\(/, ctx: "loop", bounded: /NxPerf\s*\.\s*(spawnAllowed|take|queue)\b/,
    fix: "Spawning inside a loop ($1) multiplies entities. Check NxPerf.spawnAllowed(\"<feature>\", chunk) before each spawn (perf.max-entities-per-second, perf.max-entities-per-chunk)." },
  { id: "perf-explosion-in-loop", re: /\.(createExplosion)\s*\(/, ctx: "loop", bounded: /NxPerf\s*\.\s*(rate|take)\b/,
    fix: "Explosions inside a loop chain into each other. Rate-limit them with NxPerf.rate(\"explosions\", 5) and cap the power at 4." },
  { id: "perf-chunk-load-in-loop", re: /\.(getChunkAt|loadChunk|getChunkAtAsync|setChunkForceLoaded|addPluginChunkTicket)\s*\(/, ctx: "loop", bounded: /NxPerf\s*\.\s*(take|queue)\b|isChunkLoaded/,
    fix: "Loading chunks in a loop ($1) loads or generates terrain without limit. Only touch chunks that are already loaded (isChunkLoaded) near players, through NxPerf.queue(...)." },
  { id: "perf-block-loop", re: /\.(setType|setBlockData|breakNaturally)\s*\(/, ctx: "loop", bounded: /NxPerf\s*\.\s*(take|queue|remaining)\b/,
    fix: "Changing blocks inside a loop ($1) has no per-tick limit. Queue the changes with NxPerf.queue(...) (or check NxPerf.take(\"blocks\")) so at most perf.max-work-per-tick run per tick." },
  { id: "perf-raw-timer", re: /\.(runTaskTimer|runTaskTimerAsynchronously|scheduleSyncRepeatingTask)\s*\(/, ctx: "any", bounded: /NxPerf\s*\.\s*timer\b/,
    fix: "Repeating work must use NxPerf.timer(\"<feature>\", delayTicks, periodTicks, () -> ...) so the watchdog can measure and pause it ($1 cannot be paused)." },
  { id: "perf-call-event", re: /\.callEvent\s*\(/, ctx: "handler", bounded: /NxPerf\s*\.\s*enter\b/,
    fix: "Firing an event from inside an event handler can loop through the plugin's own handler. Guard it with if (!NxPerf.enter(\"<key>\")) return; ... finally NxPerf.exit(\"<key>\")." },
  { id: "perf-infinite-loop", re: /\bwhile\s*\(\s*true\s*\)|\bfor\s*\(\s*;\s*;\s*\)/, ctx: "any", bounded: null,
    fix: "An endless loop on the server thread freezes the server. Use a bounded loop or an NxPerf.timer that does a little work per tick." },
  { id: "perf-huge-literal", re: /\b(?:getNearbyEntities|getNearbyLivingEntities|getNearbyPlayers)\s*\(\s*(?:[\w.]+\s*,\s*)?(\d{3,})(?:\.\d+)?/, ctx: "any", bounded: null,
    fix: "A search radius of $1 blocks is far too large (work grows with the cube of the radius). Use NxPerf.radius(<configured radius>) (at most perf.max-radius)." },
];

/** files: [{rel, abs}] of .java sources. Returns [{rule, where, message, evidence}] (one per rule and file). */
function perfcheck(files, env = process.env) {
  if (!enabled(env)) return [];
  const out = [];
  for (const f of files) {
    if (/\/nxperf\/NxPerf(Core)?\.java$/.test(f.rel)) continue;
    const raw = fs.readFileSync(f.abs, "utf8");
    const src = stripComments(raw);
    const lines = src.split("\n");
    const loops = loopRanges(src), handlers = handlerRanges(src);
    const inLoop = (n) => loops.some(([a, b]) => n > a && n <= b) || loops.some(([a, b]) => n === a && a === b);
    const inHandler = (n) => handlers.some((h) => n > h.from && n <= h.to);
    for (const r of PERF_RULES) {
      if (r.bounded && r.bounded.test(src)) continue;
      for (let i = 0; i < lines.length; i++) {
        const m = lines[i].match(r.re);
        if (!m) continue;
        const n = i + 1;
        if (r.ctx === "loop" && !inLoop(n)) continue;
        if (r.ctx === "handler" && !inHandler(n)) continue;
        out.push({ rule: r.id, where: `${f.rel}:${n}`, message: r.fix.replace(/\$(\d)/g, (_, k) => m[+k] || ""), evidence: raw.split("\n")[i].trim().slice(0, 160) });
        break;
      }
    }
  }
  return out;
}

/**
 * config.yml DEFAULTS above the recommended maxima (per-tick > 256, radius > 64 blocks, mob mirroring on). Advice to the
 * model about the shipped default only: the owner may raise any of them later and the code must honour that (D-62).
 */
function configCheck(ws, env = process.env) {
  if (!enabled(env)) return [];
  let y;
  try { y = fs.readFileSync(path.join(ws, "src/main/resources/config.yml"), "utf8"); } catch { return []; }
  const out = [];
  y.split("\n").forEach((l, i) => {
    const m = /^\s*([A-Za-z0-9_.-]+)\s*:\s*(-?\d+(?:\.\d+)?|true|false)\s*(?:#.*)?$/.exec(l);
    if (!m || /^\s*(auto-disable|tps-floor|window-seconds|max-work-per-tick|max-ms-per-tick|max-entities-per-second|max-entities-per-chunk|max-queue|max-radius|max-spawns-per-second|share|status-log-seconds)\s*:/.test(l)) return;
    const [k, v] = [m[1].toLowerCase(), m[2]];
    const n = Number(v);
    if (/(per-?tick|batch|per-?cycle)/.test(k) && n > 256) out.push({ rule: "perf-config-per-tick", where: `src/main/resources/config.yml:${i + 1}`, message: `${m[1]}: a default of ${v} is above the recommended 256 work items per tick. Ship a default of 64 or less; when the owner raises it, honour the value (log one warning) and spread the work with NxPerf.queue / NxPerf.grant instead of clamping it.`, evidence: l.trim() });
    if (/(radius|range|distance)/.test(k) && n > 64 && !/(view|chat|message|teleport|tp|spawn-?radius|border)/.test(k)) out.push({ rule: "perf-config-radius", where: `src/main/resources/config.yml:${i + 1}`, message: `${m[1]}: a default of ${v} blocks is above the recommended 64 for repeated work. Ship a default of 16 or less and pass the configured value through NxPerf.radius(...) (it honours the owner's value and warns above 64).`, evidence: l.trim() });
    if (/(mirror|copy|clone|duplicate|replicate)-?(mobs?|entit|spawns?)/.test(k) && v === "true") out.push({ rule: "perf-config-mob-copy", where: `src/main/resources/config.yml:${i + 1}`, message: `${m[1]}: copying mobs must default to false (an operator can enable it; then use NxPerf.spawnAllowed).`, evidence: l.trim() });
  });
  return out;
}

module.exports = { PERF_VERSION, CONFIG_SECTION, enabled, inject, patchMain, watchdogSources, mainClassOf, perfPackageOf, perfcheck, configCheck, PERF_RULES, loopRanges, stripComments };
# Nxeon Mod Builder build service.
# Base: claudebox (node 22 + Claude Code CLI + iptables egress allowlist).
FROM claudebox:14f689d

USER root
# Optional (0.5): pin a newer Claude Code CLI than the base image ships (2.1.241), e.g.
#   docker build --build-arg CLAUDE_CODE_VERSION=2.1.280 ...   (needed for Opus 5.5 on Yakko).
# Empty = keep the base image's CLI (the tested default). Verify /health + one build after changing it.
ARG CLAUDE_CODE_VERSION=""
RUN if [ -n "$CLAUDE_CODE_VERSION" ]; then npm install -g --no-audit --no-fund "@anthropic-ai/claude-code@${CLAUDE_CODE_VERSION}" && claude --version; fi
ARG MC_VERSIONS="1.21.11 1.21.8 1.21.4 1.21.1"

# Pinned toolchain (Temurin 21.0.12.1+1 + Gradle 8.14.3), copied in from the
# Nxeon research toolchain so the image never depends on a moving download.
COPY toolchain.tgz /tmp/toolchain.tgz
RUN mkdir -p /opt/mb && tar xzf /tmp/toolchain.tgz -C /opt/mb && rm /tmp/toolchain.tgz \
 && ln -s /opt/mb/jdk-21.0.12.1+1 /opt/mb/jdk && ln -s /opt/mb/gradle-8.14.3 /opt/mb/gradle
ENV JAVA_HOME=/opt/mb/jdk
ENV PATH=/opt/mb/jdk/bin:/opt/mb/gradle/bin:$PATH

# Optional (R0, Minecraft 26.x lane): a second JDK (25) + Gradle 9 used ONLY to resolve the 26.x classpath and to
# compile versions whose registry entry is `buildable` with javaRelease 25. All args are EMPTY by default, so the
# default image is exactly the 1.21.x image. Everything is verified by sha256; a URL without its checksum fails the build.
#   docker build --build-arg JDK25_URL=https://github.com/adoptium/temurin25-binaries/releases/download/jdk-25.0.4.1%2B1/OpenJDK25U-jdk_x64_linux_hotspot_25.0.4.1_1.tar.gz \
#     --build-arg JDK25_SHA256=dbb698396d478e7fa2b1e50f4103324b2a99b90569ee27c33f2261f9215cf41e \
#     --build-arg GRADLE9_URL=https://services.gradle.org/distributions/gradle-9.8.1-bin.zip \
#     --build-arg GRADLE9_SHA256=dce76f55f8e251a3a1f130eb120f30b3d271de2b76c9b0729d316b5a1b6dc01f \
#     --build-arg 'MC26_PINS=26.2=26.2.build.133-stable 26.1.2=26.1.2.build.74-stable' ...
ARG JDK25_URL=""
ARG JDK25_SHA256=""
ARG GRADLE9_URL=""
ARG GRADLE9_SHA256=""
ARG MC26_PINS=""
RUN if [ -n "$JDK25_URL" ]; then \
      test -n "$JDK25_SHA256" && curl -fsSL -o /tmp/jdk25.tgz "$JDK25_URL" && echo "$JDK25_SHA256  /tmp/jdk25.tgz" | sha256sum -c - \
      && mkdir -p /opt/mb/jdk25 && tar xzf /tmp/jdk25.tgz -C /opt/mb/jdk25 --strip-components=1 && rm /tmp/jdk25.tgz && /opt/mb/jdk25/bin/javac -version; \
    fi; \
    if [ -n "$GRADLE9_URL" ]; then \
      test -n "$GRADLE9_SHA256" && curl -fsSL -o /tmp/gradle9.zip "$GRADLE9_URL" && echo "$GRADLE9_SHA256  /tmp/gradle9.zip" | sha256sum -c - \
      && mkdir -p /tmp/g9 && (cd /tmp/g9 && /opt/mb/jdk/bin/jar xf /tmp/gradle9.zip) && mv /tmp/g9/gradle-* /opt/mb/gradle9 && chmod +x /opt/mb/gradle9/bin/gradle \
      && rm -rf /tmp/gradle9.zip /tmp/g9; \
    fi
COPY tools/gen-classpath-26.sh /opt/mb/tools/gen-classpath-26.sh

COPY template /opt/mb/template
COPY package.json /opt/mb/app/package.json
RUN cd /opt/mb/app && npm install --omit=dev --no-audit --no-fund && chown -R claude:claude /opt/mb

# Pre-warm the Gradle cache for every supported version and record the exact
# compile classpath. This is the ONLY step that talks to repo.papermc.io /
# repo.maven.apache.org, and it happens at image build time (outside the
# runtime egress firewall). Runtime builds are fully offline.
USER claude
ENV GRADLE_USER_HOME=/opt/mb/gradle-home
RUN set -e; mkdir -p /opt/mb/classpath; for v in $MC_VERSIONS; do \
      gradle --no-daemon -q -p /opt/mb/template writeClasspath -PmcApi=${v}-R0.1-SNAPSHOT -PcpOut=/opt/mb/classpath/${v}.txt; \
      test -s /opt/mb/classpath/${v}.txt; \
    done; rm -rf /opt/mb/template/.gradle /opt/mb/template/build; ls -la /opt/mb/classpath
# Class index per version (every class name on the compile classpath), used by
# precheck.js to turn "cannot find symbol" into "this class lives in package X".
RUN set -e; for v in $MC_VERSIONS; do \
      for j in $(tr ':' ' ' < /opt/mb/classpath/${v}.txt); do jar tf "$j" | grep '\.class$' || true; done | sort -u > /opt/mb/classpath/${v}.classes.txt; \
      test -s /opt/mb/classpath/${v}.classes.txt; \
    done; wc -l /opt/mb/classpath/*.classes.txt

# Optional (R0): classpath for each pinned 26.x Paper API ("id=coordinate", exact stable builds only), resolved on JDK 25 + Gradle 9.
# Empty MC26_PINS = skipped. Resolving a version here does NOT make it buildable: that is the registry's `buildable` flag.
RUN set -e; for pin in $MC26_PINS; do \
      JAVA25_HOME=/opt/mb/jdk25 GRADLE9_HOME=/opt/mb/gradle9 bash /opt/mb/tools/gen-classpath-26.sh "${pin%%=*}" "${pin#*=}" /opt/mb/classpath; \
    done; rm -rf /opt/mb/template/.gradle /opt/mb/template/build

USER root
RUN mkdir -p /work /data && chown claude:claude /work /data
USER claude
COPY --chown=claude:claude server.js scan.js prompts.js route.js precheck.js live.js usage.js autofix.js jar.js import.js textures.js sound-spec.js sounds.js creature-spec.js creatures.js capabilities.js datapack-spec.js datapacks.js designer-spec.js designs.js itemmodels.js itemmodel-spec.js release.js catalog.js catalog-mcp.js config-spec.js configs.js liveassets.js planner.js coach.js perf.js version.js equipment.js equipment-spec.js bank.js recipes.js auxgate.js capacity.js scheduler.js /opt/mb/app/
# Data files the modules above read at startup (prompt examples, sound catalog). A missing one silently degrades the prompts.
COPY --chown=claude:claude texture-example.json sound-example.json sound-catalog.json sound-catalog.txt datapack-example.json worldgen-example.json creature-example.json designer-example.json designer-gameplay-example.json designer-boss-example.json designer-hud-example.json itemmodel-example.json /opt/mb/app/
# OWNER: copy lib/cyrus/versions/registry.json next to this Dockerfile before building (server.js reads /opt/mb/app/registry.json:
# the image has no lib/). Optional glob so a build without it still works (26.x then stays non-buildable).
COPY --chown=claude:claude package.json registry.jso[n] /opt/mb/app/
# Cyrus import (inert until the portal flag cyrus_import_enabled is on): the dependency allowlist manifest and its jars.
# OWNER: copy lib/cyrus/import/deps.json next to this Dockerfile before building, then the jars are fetched and
# checksum-verified at image build time (never at build-request time). Without the file the step is skipped and
# imports that need a dependency answer "not installed".
COPY --chown=claude:claude tools/fetch-import-deps.js /opt/mb/tools/fetch-import-deps.js
# (package.json always matches, so the optional deps.json glob never fails the COPY)
COPY --chown=claude:claude package.json deps.jso[n] /opt/mb/app/
USER root
RUN if [ -f /opt/mb/app/deps.json ]; then node /opt/mb/tools/fetch-import-deps.js /opt/mb/app/deps.json /opt/mb/deps && chmod 755 /opt/mb/deps; fi
USER claude
COPY --chown=claude:claude entrypoint.sh /opt/mb/entrypoint.sh
COPY --chown=claude:claude sheets /opt/mb/app/sheets
COPY --chown=claude:claude rules /opt/mb/app/rules
# Cyrus starter bank (prebuilt verified mods) + recipe memory (verified mechanic patterns); both inert unless MB_STARTER_BANK / MB_RECIPES
COPY --chown=claude:claude bank /opt/mb/app/bank
COPY --chown=claude:claude recipes /opt/mb/app/recipes
# Cyrus perf safety: the audited watchdog sources injected into every generated plugin (perf.js)
COPY --chown=claude:claude perf/src /opt/mb/app/perf/src
ENV MB_VERSIONS="1.21.11 1.21.8 1.21.4 1.21.1"
WORKDIR /data
EXPOSE 3000
# Our entrypoint = the base image's (firewall + drop to the claude user) with a wider auth check and EXTRA_ALLOWED_DOMAINS.
ENTRYPOINT ["/bin/bash", "/opt/mb/entrypoint.sh"]
CMD ["node", "/opt/mb/app/server.js"]
