"use strict";
// Deterministic fixes for the most common, purely mechanical build errors (service 0.5+).
// Applied by the service BEFORE a model repair is spent; anything not certain is left to
// the model. Every fix touches only the exact line javac (or the validator) pointed at,
// and only when the real Paper jar of that version has exactly one right answer.
//
//   fixMainFinal(text)            "public final class X extends JavaPlugin" -> drop final
//   fixCompile(javacOut, ws, v)   from javac output:
//     wrong-import   import org.bukkit.configuration.FileConfiguration;  (class lives elsewhere)
//                    -> the unique FQN in the Paper API packages (org.bukkit.configuration.file.FileConfiguration)
//     missing-import cannot find symbol class NamespacedKey (no import) -> add the unique API import
//                    (never for names that are common JDK classes)
//   fixBlankFinal(javacOut, ws)   'variable X might not have been initialized' on a blank final field read by a lambda in a field
//                                 initializer (e.g. a NxPerf.queue(...) field using `plugin`) -> drop `final` (no model turn)
//   fixGameRules(files, v)       1.21.11+: GameRule.X (deprecated for removal) -> GameRules.Y (same name or same-meaning rename)
//     renamed-const  Attribute.GENERIC_SCALE on 1.21.11 / Attribute.MAX_HEALTH on 1.21.1
//                    -> the one field of that type whose name matches once the GENERIC_/PLAYER_/
//                       ZOMBIE_ prefix and underscores are ignored
//
// Seen in the real build records (VM 88001, 138 builds): 7 of the 13 builds that needed a
// model repair failed on exactly these (final main x2, FileConfiguration/NumberFormat package
// x2, Attribute prefixes x3). Unit tests: test/modbuilder-efficiency.test.ts.
// MB_AUTOFIX=off disables it.

const fs = require("fs");
const path = require("path");

const API_PKG = /^(org\.bukkit|io\.papermc|net\.kyori|com\.destroystokyo)\./;
