// never guess an import for these.
const JDK_COMMON = new Set(("List Map Set HashMap HashSet ArrayList LinkedList Optional Collection Collections Iterator Objects Random UUID " +
  "Duration Instant LocalDate LocalDateTime ZonedDateTime TimeUnit Color Event File Files Path Paths Level Logger Pattern Matcher " +
  "Arrays Comparator Function Supplier Consumer Predicate Stream Collectors Entry Queue Deque ArrayDeque Locale Date Calendar " +
  "Timer TimerTask Thread Runnable Callable Executor ExecutorService CompletableFuture AtomicInteger AtomicLong AtomicBoolean " +
  "ConcurrentHashMap ThreadLocalRandom Math StringBuilder Character Integer Long Double Float Boolean Byte Short Number Record " +
  "Type Field Method Annotation Reference Range Vector NumberFormat DecimalFormat SimpleDateFormat MessageFormat").split(/\s+/));

