/** Work units left this tick for budget `name`. */
public static int remaining(String name) {
  NxPerfCore.Budget b = BUDGETS.computeIfAbsent(name, k -> new NxPerfCore.Budget(k, S.maxWorkPerTick));
  return paused ? 0 : b.remaining(Bukkit.getCurrentTick());
}

/** May the plugin spawn one more entity for `name` now? perf.max-entities-per-second and perf.max-entities-per-chunk. */
public static boolean spawnAllowed(String name, Chunk chunk) {
  if (paused) return false;
  if (chunk != null) {
    int living = 0;
    for (Entity e : chunk.getEntities()) if (e instanceof LivingEntity && !(e instanceof Player)) living++;
    if (living >= S.maxEntitiesPerChunk) return false;
  }
  NxPerfCore.Rate r = RATES.computeIfAbsent("spawn:" + name, k -> new NxPerfCore.Rate(S.maxEntitiesPerSecond));
  return r.take(System.nanoTime());
}

/** A per-second rate limit (e.g. explosions, effects). */
public static boolean rate(String name, double perSecond) {
  if (paused) return false;
  return RATES.computeIfAbsent("rate:" + name, k -> new NxPerfCore.Rate(perSecond)).take(System.nanoTime());
}

