// Cheap checks around the compiler, all offline and deterministic:
//   precheck(): before javac, match the reviewed failure rules' patterns
//     (rules/failure-rules.json) against the generated sources for this Paper
//     version. A hit becomes a build problem with a precise fix instruction.
//     Catches known-bad API use (e.g. Attribute.SCALE on 1.21.1) with a better
//     message than javac, and patterns javac cannot see.
//   apiHints(): after a failed javac, look the missing symbols up in the real
//     Paper jar for this version (javap + the class index built at image build)
//     and append "this class has X, closest names are Y" to the error text, so
//     the repair (often on a cheap model) does not have to guess.

const fs = require("fs");
const path = require("path");
const { execFileSync } = require("child_process");

const RULES_FILE = process.env.MB_RULES_FILE || path.join(__dirname, "rules", "failure-rules.json");
const CP_DIR = process.env.MB_CP_DIR || "/opt/mb/classpath";

let RULES = { version: "none", rules: [] };
try { RULES = JSON.parse(fs.readFileSync(RULES_FILE, "utf8")); } catch (e) { process.stderr.write(`rules not loaded: ${e.message}\n`); }

function rulesFor(v) {
  return (RULES.rules || []).filter((r) => (r.versions || ["*"]).some((x) => x === "*" || x === v));
}

function stripComments(src) {
  return src.replace(/\/\*[\s\S]*?\*\//g, (m) => m.replace(/[^\n]/g, " ")).replace(/\/\/[^\n]*/g, "");
}

/** files: [{rel, abs}] of .java sources. Returns [{rule, where, message}] (deduped by rule+file). */
function precheck(files, v) {
  const out = [];
