  for (const f of files) {
    const src = stripComments(fs.readFileSync(f.abs, "utf8"));
    const isMain = /\bextends\s+(org\.bukkit\.plugin\.java\.)?JavaPlugin\b/.test(src);
    const lines = src.split("\n");
    for (const r of rules) {
      if (r.scope === "main" && !isMain) continue;
      // `unless` (file-level): the rule does not apply to a file that also matches it (e.g. a PlayerMoveEvent handler
      // that already checks hasChangedBlock()).
      if (r.unless && new RegExp(r.unless, "m").test(src)) continue;
      // `requires` (file-level, the opposite): the rule only applies to a file that also matches it (e.g. getMapList AND a
      // getOrDefault call with a string key).
      if (r.requires && !new RegExp(r.requires, "m").test(src)) continue;
      const re = new RegExp(r.pattern, "m");
      for (let i = 0; i < lines.length; i++) {
        const m = lines[i].match(re);
        if (!m) continue;
        const key = `${r.id}|${f.rel}|${m[0]}`;
        if (seen.has(key)) continue;
        seen.add(key);
        out.push({ rule: r.id, where: `${f.rel}:${i + 1}`, message: (r.fix || r.rule).replace(/\$(\d)/g, (_, n) => m[+n] || ""), evidence: lines[i].trim().slice(0, 160) });
      }
    }
  }
  return out;
}

// ------------------------------------------------------------ API hints ----
const memberCache = new Map(); // `${v}|${fqn}` -> {fields:[], methods:[]} | null
const classIndexCache = new Map(); // v -> Map(simpleName -> [fqn])

function classIndex(v) {
  if (classIndexCache.has(v)) return classIndexCache.get(v);
  const m = new Map();
  try {
    for (const line of fs.readFileSync(path.join(CP_DIR, `${v}.classes.txt`), "utf8").split("\n")) {
      if (!line.endsWith(".class") || line.includes("$")) continue;
      const fqn = line.slice(0, -6).replace(/\//g, ".");
      const simple = fqn.slice(fqn.lastIndexOf(".") + 1);
      if (!m.has(simple)) m.set(simple, []);
      m.get(simple).push(fqn);
    }
  } catch { /* index missing: hints degrade to javap-only */ }
  classIndexCache.set(v, m);
  return m;
}

function members(v, fqn) {
  const k = `${v}|${fqn}`;
  if (memberCache.has(k)) return memberCache.get(k);
  let res = null;
  try {
    const cp = fs.readFileSync(path.join(CP_DIR, `${v}.txt`), "utf8").trim();
    const out = execFileSync("javap", ["-public", "-cp", cp, fqn], { encoding: "utf8", timeout: 30000, maxBuffer: 16 * 1024 * 1024, env: { PATH: process.env.PATH, JAVA_HOME: process.env.JAVA_HOME } });
    const fields = [], methods = [];
    for (const l of out.split("\n")) {
      const fm = l.match(/^\s+public\s+(?:static\s+)?(?:final\s+)?[\w.$<>?,\[\] ]+\s+(\w+);$/);
      if (fm) { fields.push(fm[1]); continue; }
      const mm = l.match(/^\s+public\s+.*?([\w$]+)\(([^)]*)\)/);
      if (mm && !mm[1].includes("$") && !fqn.endsWith("." + mm[1])) methods.push(`${mm[1]}(${mm[2].split(",").filter(Boolean).map((s) => s.trim().split(".").pop()).join(", ")})`);
    }
    res = { fields: [...new Set(fields)], methods: [...new Set(methods)] };
  } catch { res = null; }
  memberCache.set(k, res);
  return res;
}

function lev(a, b) {
  const d = Array.from({ length: a.length + 1 }, (_, i) => [i]);
  for (let j = 1; j <= b.length; j++) d[0][j] = j;
  for (let i = 1; i <= a.length; i++) for (let j = 1; j <= b.length; j++) d[i][j] = Math.min(d[i - 1][j] + 1, d[i][j - 1] + 1, d[i - 1][j - 1] + (a[i - 1] === b[j - 1] ? 0 : 1));
  return d[a.length][b.length];
}
function closest(name, pool, n = 6) {
  const norm = (s) => s.toUpperCase().replace(/^(GENERIC|PLAYER|ZOMBIE)_/, "").replace(/_/g, "");
  const nn = norm(name);
  return pool
    .map((p) => {
      const pn = norm(p.split("(")[0]);
      let s = lev(nn, pn);
      if (pn === nn) s = -2;
      else if (pn.includes(nn) || nn.includes(pn)) s = Math.min(s, 1);
      return [s, p];
    })
    .filter(([s]) => s <= Math.max(2, Math.floor(nn.length / 3)))
    .sort((a, b) => a[0] - b[0])
    .slice(0, n)
    .map(([, p]) => p);
}

function resolveType(simple, srcText, v) {
  simple = simple.replace(/<.*$/, "").trim();
  if (simple.includes(".")) return simple;
  const imp = srcText.match(new RegExp(`^\\s*import\\s+([\\w.]+\\.${simple})\\s*;`, "m"));
  if (imp) return imp[1];
  const c = (classIndex(v).get(simple) || []);
  const pref = c.find((x) => /^(org\.bukkit|io\.papermc|net\.kyori|com\.destroystokyo)\./.test(x)) || c[0];
  return pref || null;
}

/** Returns extra text to append to javac output (or ""). */
function apiHints(javacOut, ws, v) {
  const hints = [];
  const done = new Set();
  // javac "cannot find symbol" blocks: file:line: error ...\n  code\n  ^\n  symbol: ...\n  location: ...
  const re = /^([^\s:]+\.java):(\d+): error: cannot find symbol\n[\s\S]*?\n\s+symbol:\s+(variable|method|class)\s+([\w$]+)(?:\(([^)]*)\))?\n\s+location:\s+(?:(?:class|interface|enum)\s+([\w.$<>,? ]+)|variable\s+\w+\s+of\s+type\s+([\w.$<>,? ]+)|package\s+([\w.]+))/gm;
  let m;
  while ((m = re.exec(javacOut)) && hints.length < 12) {
    const [, file, , kind, name, , locClass, locVarType, locPkg] = m;
    let src = "";
    try { src = fs.readFileSync(path.join(ws, file), "utf8"); } catch { /* ignore */ }
    if (kind === "class") {
      const key = `class|${name}|${locPkg || ""}`;
      if (done.has(key)) continue; done.add(key);
      const c = classIndex(v).get(name) || [];
      if (c.length) hints.push(`- There is no class ${locPkg ? `${locPkg}.` : ""}${name}${locPkg ? "" : " in scope"}. In Paper ${v} ${name} is: ${c.slice(0, 4).join(", ")} (fix the import).`);
      else hints.push(`- Paper ${v} (and the JDK classes we checked) has no class named ${name}. Do not use it; use a different API.`);
      continue;
    }
    const typeName = (locClass || locVarType || "").trim();
    if (!typeName) continue;
    // The plugin's own classes (e.g. its own ScoreboardManager) are not Paper API.
    const own = typeName.replace(/<.*$/, "").split(".").pop();
    if (!typeName.includes(".") && new RegExp(`\\b(class|interface|enum|record)\\s+${own}\\b`).test(src)) continue;
    const fqn = resolveType(typeName, src, v);
    if (!fqn || !/^(org\.bukkit|io\.papermc|net\.kyori|com\.destroystokyo|net\.md_5)\./.test(fqn)) continue;
    const key = `${kind}|${fqn}|${name}`;
    if (done.has(key)) continue; done.add(key);
    const mem = members(v, fqn);
    if (!mem) continue;
    const simple = fqn.split(".").pop();
    if (kind === "variable") {
      const near = closest(name, mem.fields);
      if (!near.length && !mem.fields.length) continue;
      hints.push(near.length
        ? `- ${simple} has no ${name} in Paper ${v}. Closest existing names: ${near.join(", ")}.`
        : `- ${simple} has no ${name} in Paper ${v}. It has: ${mem.fields.slice(0, 40).join(", ")}${mem.fields.length > 40 ? ", ..." : ""}.`);
    } else {
      const near = closest(name, mem.methods.filter((x) => !/^(equals|hashCode|toString|getClass|wait|notify|notifyAll)\(/.test(x)));
      const all = [...new Set(mem.methods.map((x) => x.split("(")[0]))];
      hints.push(near.length
        ? `- ${simple}.${name}(...) does not exist in Paper ${v}. Similar methods: ${near.join("; ")}.`
        : `- ${simple}.${name}(...) does not exist in Paper ${v}. ${simple} methods include: ${all.slice(0, 45).join(", ")}${all.length > 45 ? ", ..." : ""} (inherited methods not listed).`);
    }
  }
  return hints.length ? `\n\nAPI LOOKUP (checked against the Paper ${v} jar you compile with):\n${hints.join("\n")}` : "";
}

/** Compiler warnings that are known runtime failures (rules with a "warning" regex). */
function warningCheck(warnings, v) {
  const out = [];
  for (const r of rulesFor(v).filter((x) => x.warning)) {
    const re = new RegExp(r.warning);
    const w = warnings.find((x) => re.test(x));
    if (w) out.push({ rule: r.id, where: "compiler warning", message: r.fix || r.rule, evidence: w.slice(0, 200) });
  }
  return out;
}

/**
 * plugin.yml `libraries:` makes Paper download jars from the internet at server start, outside the offline build, the scan and the
 * dependency allowlist. Never allowed, for generated AND imported builds. Returns a message or null.
 */
function librariesProblem(yml) {
  if (yml && typeof yml === "object" && yml.libraries !== undefined) {
    return "plugin.yml must not have a libraries: section (Paper would download them at runtime). Remove it.";
  }
  return null;
}

module.exports = { RULES, rulesFor, precheck, apiHints, warningCheck, classIndex, members, resolveType, librariesProblem };
